// Every number is an engine aggregate over stored rows; the CSV export is
// generated by the same engine query, so the file always matches the screen.

import React, { useState } from 'react';
import { ledger, ACCOUNT_KIND_SINGULAR, type AccountKind } from '../ledgerApi';
import { formatMonth, monthEnd, monthOf, shiftMonth, formatDate } from '../money';
import { useLedger, useLedgerQuery, Money, Btn, Empty, errText } from '../ledgerUi';
import { TransactionsView } from './TransactionsView';

type ReportId = 'incomeExpense' | 'cashFlow' | 'spending' | 'balances' | 'budgetVsActual' | 'transactions';
const REPORTS: { id: ReportId; label: string }[] = [
  { id: 'incomeExpense', label: 'Income vs expenses' },
  { id: 'cashFlow', label: 'Cash flow' },
  { id: 'spending', label: 'Spending by category' },
  { id: 'balances', label: 'Account balances' },
  { id: 'budgetVsActual', label: 'Budget vs actual' },
  { id: 'transactions', label: 'Transaction history' },
];

type Preset = 'thisMonth' | 'lastMonth' | 'last3' | 'last6' | 'last12' | 'ytd' | 'lastYear' | 'custom';

function presetRange(p: Preset, today: string): { from: string; to: string } {
  const m = monthOf(today);
  const y = Number(today.slice(0, 4));
  switch (p) {
    case 'lastMonth': { const l = shiftMonth(m, -1); return { from: `${l}-01`, to: monthEnd(l) }; }
    case 'last3': return { from: `${shiftMonth(m, -2)}-01`, to: monthEnd(m) };
    case 'last6': return { from: `${shiftMonth(m, -5)}-01`, to: monthEnd(m) };
    case 'last12': return { from: `${shiftMonth(m, -11)}-01`, to: monthEnd(m) };
    case 'ytd': return { from: `${y}-01-01`, to: today };
    case 'lastYear': return { from: `${y - 1}-01-01`, to: `${y - 1}-12-31` };
    default: return { from: `${m}-01`, to: monthEnd(m) };
  }
}

interface IE { rows: { month: string; income: number; expenses: number; uncategorized: number; net: number }[]; totals: { income: number; expenses: number; uncategorized: number; net: number } }
interface CF { openingBalance: number; closingBalance: number; rows: { month: string; inflow: number; outflow: number; net: number; endingBalance: number }[] }
interface SP { rows: { categoryId: number; category: string; group: string; spent: number; transactions: number }[]; total: number; uncategorizedSpent: number; uncategorizedCount: number }
interface BA { asOf: string; rows: { accountId: number; name: string; kind: AccountKind; archived: boolean; balance: number }[]; total: number }
interface BVA { rows: { categoryId: number; category: string; group: string; assigned: number; spent: number; difference: number }[]; totals: { assigned: number; spent: number; difference: number } }

export const ReportsView: React.FC = () => {
  const { today, toast, go } = useLedger();
  const [report, setReport] = useState<ReportId>(() => { try { return (sessionStorage.getItem('dex-ledger-report') as ReportId) || 'incomeExpense'; } catch { return 'incomeExpense'; } });
  const [preset, setPreset] = useState<Preset>('last6');
  const [custom, setCustom] = useState(() => presetRange('last6', today));
  const range = preset === 'custom' ? custom : presetRange(preset, today);
  const valid = range.from <= range.to;

  const pick = (r: ReportId) => { setReport(r); try { sessionStorage.setItem('dex-ledger-report', r); } catch { /* ignore */ } };

  const params = report === 'balances' ? { asOf: range.to } : { from: range.from, to: range.to };
  const q = useLedgerQuery<unknown>(() => (report === 'transactions' || !valid ? Promise.resolve(null) : ledger.report(report, params)), [report, range.from, range.to]);

  const exportCsv = async () => {
    try {
      const r = await ledger.reportCsv(report, params);
      const s = await ledger.saveText(`ledger-${report}-${range.from}-to-${range.to}.csv`, r.csv);
      if (!s.canceled) toast('Report exported', 'success');
    } catch (e) { toast(errText(e), 'error'); }
  };

  const body = (() => {
    if (!valid) return <div className="lg-banner lg-warn">The start date is after the end date.</div>;
    if (report === 'transactions') return null;
    if (q.error) return <div className="lg-banner lg-error">{q.error}</div>;
    if (!q.data) return <div className="lg-muted">Calculating…</div>;
    switch (report) {
      case 'incomeExpense': return <IncomeExpense d={q.data as IE} />;
      case 'cashFlow': return <CashFlow d={q.data as CF} />;
      case 'spending': return <Spending d={q.data as SP} onOpen={(id) => go('transactions', { categoryId: id })} />;
      case 'balances': return <Balances d={q.data as BA} />;
      case 'budgetVsActual': return <BudgetVsActual d={q.data as BVA} />;
    }
    return null;
  })();

  return (
    <>
      <div className="lg-toolbar">
        <h1>Reports</h1>
        <select className="lg-input" aria-label="Report" style={{ width: 200 }} value={report} onChange={e => pick(e.target.value as ReportId)}>
          {REPORTS.map(r => <option key={r.id} value={r.id}>{r.label}</option>)}
        </select>
        {report !== 'transactions' && (
          <>
            <select className="lg-input" aria-label="Date range" style={{ width: 150 }} value={preset} onChange={e => setPreset(e.target.value as Preset)}>
              <option value="thisMonth">This month</option><option value="lastMonth">Last month</option><option value="last3">Last 3 months</option>
              <option value="last6">Last 6 months</option><option value="last12">Last 12 months</option><option value="ytd">Year to date</option>
              <option value="lastYear">Last year</option><option value="custom">Custom…</option>
            </select>
            {preset === 'custom' && (
              <>
                {report !== 'balances' && <input className="lg-input" type="date" aria-label="From" value={custom.from} onChange={e => setCustom(c => ({ ...c, from: e.target.value }))} style={{ width: 140 }} />}
                <input className="lg-input" type="date" aria-label={report === 'balances' ? 'As of' : 'To'} value={custom.to} onChange={e => setCustom(c => ({ ...c, to: e.target.value }))} style={{ width: 140 }} />
              </>
            )}
            <span className="lg-sub">{report === 'balances' ? `As of ${formatDate(range.to)}` : `${formatDate(range.from)} – ${formatDate(range.to)}`}</span>
          </>
        )}
        <span className="lg-spacer" />
        {report !== 'transactions' && <Btn small icon="export" onClick={exportCsv} disabled={!valid}>Export CSV</Btn>}
        {report !== 'transactions' && <Btn small icon="printer" onClick={() => window.print()}>Print</Btn>}
      </div>
      {report === 'transactions' ? <TransactionsView selectedId={null} /> : <div className="lg-scroll"><div className="lg-pad">{body}</div></div>}
    </>
  );
};

const max = (xs: number[]) => Math.max(1, ...xs.map(Math.abs));
const pct = (v: number, m: number) => `${Math.max(0, Math.min(100, (Math.abs(v) / m) * 100))}%`;

const IncomeExpense: React.FC<{ d: IE }> = ({ d }) => {
  const m = max(d.rows.flatMap(r => [r.income, r.expenses]));
  const any = d.rows.some(r => r.income || r.expenses || r.uncategorized);
  return (
    <>
      <div className="lg-summary">
        <div><div className="lg-summary-label">Income</div><div className="lg-summary-value"><Money minor={d.totals.income} /></div></div>
        <div><div className="lg-summary-label">Expenses</div><div className="lg-summary-value"><Money minor={d.totals.expenses} /></div></div>
        <div><div className="lg-summary-label">Uncategorised</div><div className="lg-summary-value"><Money minor={d.totals.uncategorized} sign /></div></div>
        <div><div className="lg-summary-label">Net</div><div className="lg-summary-value"><Money minor={d.totals.net} sign /></div></div>
      </div>
      {!any ? <Empty icon="bar-chart-2" title="No categorised income or spending in this period" /> : (
        <>
          <div className="lg-section-title">By month <span className="lg-muted" style={{ fontWeight: 400 }}>· <span style={{ color: 'var(--color-accent)' }}>■</span> income <span>■</span> expenses</span></div>
          <div className="lg-bars" role="img" aria-label="Income and expenses by month">
            {d.rows.map(r => (
              <div key={r.month} className="lg-bar-row">
                <span className="lg-muted">{formatMonth(r.month, 'short')}</span>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                  <div className="lg-bar-track"><div className="lg-bar-fill" style={{ width: pct(r.income, m) }} /></div>
                  <div className="lg-bar-track"><div className="lg-bar-fill lg-alt" style={{ width: pct(r.expenses, m) }} /></div>
                </div>
                <span className="lg-num" style={{ minWidth: 90, textAlign: 'right' }}><Money minor={r.net} sign /></span>
              </div>
            ))}
          </div>
        </>
      )}
      <div className="lg-section-title">Table</div>
      <div className="lg-panel lg-hscroll">
        <table className="lg-table">
          <thead><tr><th>Month</th><th className="lg-r">Income</th><th className="lg-r">Expenses</th><th className="lg-r lg-hide-xs">Uncategorised</th><th className="lg-r">Net</th></tr></thead>
          <tbody>
            {d.rows.map(r => <tr key={r.month}><td>{formatMonth(r.month)}</td><td className="lg-r"><Money minor={r.income} /></td><td className="lg-r"><Money minor={r.expenses} /></td><td className="lg-r lg-hide-xs"><Money minor={r.uncategorized} sign /></td><td className="lg-r"><Money minor={r.net} sign /></td></tr>)}
            <tr className="lg-budget-group"><td>Total</td><td className="lg-r"><Money minor={d.totals.income} /></td><td className="lg-r"><Money minor={d.totals.expenses} /></td><td className="lg-r lg-hide-xs"><Money minor={d.totals.uncategorized} sign /></td><td className="lg-r"><Money minor={d.totals.net} sign /></td></tr>
          </tbody>
        </table>
      </div>
    </>
  );
};

const CashFlow: React.FC<{ d: CF }> = ({ d }) => {
  const m = max(d.rows.map(r => r.endingBalance));
  return (
    <>
      <div className="lg-summary">
        <div><div className="lg-summary-label">Opening balance</div><div className="lg-summary-value"><Money minor={d.openingBalance} /></div></div>
        <div><div className="lg-summary-label">Money in</div><div className="lg-summary-value"><Money minor={d.rows.reduce((s, r) => s + r.inflow, 0)} /></div></div>
        <div><div className="lg-summary-label">Money out</div><div className="lg-summary-value"><Money minor={d.rows.reduce((s, r) => s + r.outflow, 0)} /></div></div>
        <div><div className="lg-summary-label">Closing balance</div><div className="lg-summary-value"><Money minor={d.closingBalance} /></div></div>
      </div>
      <div className="lg-muted" style={{ fontSize: 11.5, marginTop: 6 }}>Money in and out include every non-transfer transaction, categorised or not. Balances are the total of all accounts at each month end.</div>
      <div className="lg-section-title">Ending balance by month</div>
      <div className="lg-bars" role="img" aria-label="Ending balance by month">
        {d.rows.map(r => (
          <div key={r.month} className="lg-bar-row">
            <span className="lg-muted">{formatMonth(r.month, 'short')}</span>
            <div className="lg-bar-track"><div className={`lg-bar-fill ${r.endingBalance < 0 ? 'lg-alt' : ''}`} style={{ width: pct(r.endingBalance, m) }} /></div>
            <span className="lg-num" style={{ minWidth: 90, textAlign: 'right' }}><Money minor={r.endingBalance} /></span>
          </div>
        ))}
      </div>
      <div className="lg-section-title">Table</div>
      <div className="lg-panel lg-hscroll">
        <table className="lg-table">
          <thead><tr><th>Month</th><th className="lg-r">Money in</th><th className="lg-r">Money out</th><th className="lg-r">Net</th><th className="lg-r">Ending balance</th></tr></thead>
          <tbody>{d.rows.map(r => <tr key={r.month}><td>{formatMonth(r.month)}</td><td className="lg-r"><Money minor={r.inflow} /></td><td className="lg-r"><Money minor={r.outflow} /></td><td className="lg-r"><Money minor={r.net} sign /></td><td className="lg-r"><Money minor={r.endingBalance} /></td></tr>)}</tbody>
        </table>
      </div>
    </>
  );
};

const Spending: React.FC<{ d: SP; onOpen: (categoryId: number) => void }> = ({ d, onOpen }) => {
  const m = max(d.rows.map(r => r.spent));
  if (!d.rows.length && !d.uncategorizedSpent) return <Empty icon="pie-chart" title="No spending in this period" />;
  return (
    <>
      <div className="lg-summary">
        <div><div className="lg-summary-label">Spent (categorised)</div><div className="lg-summary-value"><Money minor={d.total} /></div></div>
        <div><div className="lg-summary-label">Uncategorised spending</div><div className="lg-summary-value"><Money minor={d.uncategorizedSpent} /></div></div>
      </div>
      <div className="lg-section-title">By category</div>
      <div className="lg-bars">
        {d.rows.map(r => (
          <div key={r.categoryId} className="lg-bar-row">
            <button type="button" className="lg-btn lg-btn-ghost lg-btn-sm" style={{ justifyContent: 'flex-start', overflow: 'hidden' }} onClick={() => onOpen(r.categoryId)} title={`${r.group} › ${r.category}`}>{r.category}</button>
            <div className="lg-bar-track"><div className="lg-bar-fill" style={{ width: pct(r.spent, m) }} /></div>
            <span className="lg-num" style={{ minWidth: 120, textAlign: 'right' }}><Money minor={r.spent} /> <span className="lg-muted">{d.total ? `${Math.round((r.spent / d.total) * 100)}%` : ''}</span></span>
          </div>
        ))}
      </div>
      <div className="lg-muted" style={{ fontSize: 11.5, marginTop: 8 }}>Refunds to a category reduce its spending. A category whose refunds exceed its spending shows a negative amount.</div>
    </>
  );
};

const Balances: React.FC<{ d: BA }> = ({ d }) => (
  <div className="lg-panel lg-hscroll">
    <table className="lg-table">
      <thead><tr><th>Account</th><th className="lg-hide-xs">Type</th><th className="lg-r">Balance on {formatDate(d.asOf)}</th></tr></thead>
      <tbody>
        {d.rows.map(r => <tr key={r.accountId}><td>{r.name}{r.archived && <span className="lg-tag" style={{ marginLeft: 6 }}>archived</span>}</td><td className="lg-muted lg-hide-xs">{ACCOUNT_KIND_SINGULAR[r.kind]}</td><td className="lg-r"><Money minor={r.balance} /></td></tr>)}
        <tr className="lg-budget-group"><td>Total</td><td className="lg-hide-xs" /><td className="lg-r"><Money minor={d.total} /></td></tr>
      </tbody>
    </table>
  </div>
);

const BudgetVsActual: React.FC<{ d: BVA }> = ({ d }) => {
  if (!d.rows.length) return <Empty icon="pie-chart" title="Nothing assigned or spent in these months" />;
  return (
    <>
      <div className="lg-muted" style={{ fontSize: 11.5, marginBottom: 8 }}>Whole months in the range. Difference = assigned − spent; negative means overspent.</div>
      <div className="lg-panel lg-hscroll">
        <table className="lg-table">
          <thead><tr><th>Category</th><th className="lg-r">Assigned</th><th className="lg-r">Spent</th><th className="lg-r">Difference</th></tr></thead>
          <tbody>
            {d.rows.map(r => <tr key={r.categoryId}><td><span className="lg-muted">{r.group} › </span>{r.category}</td><td className="lg-r"><Money minor={r.assigned} /></td><td className="lg-r"><Money minor={r.spent} /></td><td className="lg-r"><Money minor={r.difference} tone="available" /></td></tr>)}
            <tr className="lg-budget-group"><td>Total</td><td className="lg-r"><Money minor={d.totals.assigned} /></td><td className="lg-r"><Money minor={d.totals.spent} /></td><td className="lg-r"><Money minor={d.totals.difference} sign /></td></tr>
          </tbody>
        </table>
      </div>
    </>
  );
};
